import json

PRICES = {
    "Eastwatch": {"fish": 55, "silk": 44, "timber": 41, "amber": 14},
    "Ashford": {"fish": 37, "silk": 17, "timber": 51, "amber": 46},
    "Marlow": {"fish": 38, "silk": 41, "timber": 59, "amber": 35"},
}
CAP = 20
LAST_DAY = 8

start = json.load(open("save/state.json"))
print("Start state:", start)
towns = list(PRICES)
goods = list(PRICES[towns[0]].keys())
print("Goods:", goods, "| Capacity:", CAP, "| Last day:", LAST_DAY)

print("\nSpread (price at B minus price at A), per unit, by leg:")
print("%-30s" % "Leg" + "".join("%10s" % g for g in goods))
for A in towns:
    for B in towns:
        if A == B:
            continue
        cells = []
        for g in goods:
            cells.append("%10d" % (PRICES[B][g] - PRICES[A][g]))
        print("%-30s" % (A + " -> " + B) + "".join(cells))

print("\nBest profitable good to carry on each leg:")
for A in towns:
    for B in towns:
        if A == B:
            continue
        best = max(goods, key=lambda g: PRICES[B][g] - PRICES[A][g])
        val = PRICES[B][best] - PRICES[A][best]
